import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    // O topo é sempre a abertura mais recente: é ela que o próximo fechamento precisa casar. O(n).
    static boolean valido(String s) {
        Deque<Character> pilha = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '(' -> pilha.push(')');
                case '[' -> pilha.push(']');
                case '{' -> pilha.push('}');
                default -> {
                    if (pilha.isEmpty() || pilha.pop() != c) return false;
                }
            }
        }
        return pilha.isEmpty();
    }
}

tests:
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void validos() {
        assertTrue(Solution.valido("{[()()]}"));
        assertTrue(Solution.valido("()[]{}"));
        assertTrue(Solution.valido(""));
    }

    @Test void invalidos() {
        assertFalse(Solution.valido("([)]"));
        assertFalse(Solution.valido("(("));
        assertFalse(Solution.valido("))"));
        assertFalse(Solution.valido("]"));
    }

    @Test void profundo() {
        String s = "(".repeat(100_000) + ")".repeat(100_000);
        assertTrue(Solution.valido(s));
        assertFalse(Solution.valido(s + "("));
    }
}

