import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    // Números empilham; operadores desempilham b (topo) e depois a. O(n).
    static int avaliarRPN(String[] tokens) {
        Deque<Integer> pilha = new ArrayDeque<>();
        for (String t : tokens) {
            if (t.length() == 1 && "+-*/".contains(t)) {
                if (pilha.size() < 2) throw new IllegalArgumentException("faltam operandos para " + t);
                int b = pilha.pop(), a = pilha.pop();
                pilha.push(switch (t) {
                    case "+" -> a + b;
                    case "-" -> a - b;
                    case "*" -> a * b;
                    default -> a / b;
                });
            } else {
                pilha.push(Integer.parseInt(t));
            }
        }
        if (pilha.size() != 1) throw new IllegalArgumentException("expressão malformada");
        return pilha.pop();
    }
}

tests:
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void exemplos() {
        assertEquals(9, Solution.avaliarRPN(new String[]{"2", "1", "+", "3", "*"}));
        assertEquals(6, Solution.avaliarRPN(new String[]{"4", "13", "5", "/", "+"}));
    }

    @Test void ordemDosOperandos() {
        assertEquals(3, Solution.avaliarRPN(new String[]{"5", "2", "-"}));
        assertEquals(-2, Solution.avaliarRPN(new String[]{"-7", "3", "/"}));
    }

    @Test void malformada() {
        assertThrows(IllegalArgumentException.class, () -> Solution.avaliarRPN(new String[]{"1", "+"}));
        assertThrows(IllegalArgumentException.class, () -> Solution.avaliarRPN(new String[]{"1", "2"}));
    }
}
